const SCI_FI = ROOT + 'kenney_ui-pack-space-expansion/PNG/Blue/Default/';
const MEDIA = '../../../reports/EXCEL_15_SMOKE/run-bc2d5460-d9d6-4cef-8cae-1a9601ae7291/content_pack_v46/assets/';
const assets = {
  ship: SHOOTER + 'playerShip2_blue.png', meteor: SHOOTER + 'Meteors/meteorGrey_big1.png',
  meteorAlt: SHOOTER + 'Meteors/meteorBrown_big1.png', laser: SHOOTER + 'Lasers/laserBlue01.png',
  shield: SHOOTER + 'Effects/shield1.png', flame: SHOOTER + 'Effects/fire00.png',
  hp: SHOOTER + 'UI/playerLife2_blue.png', buttonPrimary: SHOOTER + 'UI/buttonBlue.png', reticle: ROOT + 'kenney_ui-pack-space-expansion/Vector/Blue/crosshair_color_a.svg', // SVG twin of the recommended PNG: stays sharp at meteor size
  planet: ROOT + 'kenney_planets/Planets/planet06.png'
};
const cards = [
  {en:'Pineapple', ja:'パイナップル', vi:'Quả dứa', image:'e6c9351594601f66eabdacb7a015744e775b48f9dc8c5e8938a2452a099cfefa.jpg', enAudio:'1729d2ca253f63832ccea8c01c24fc685507b6838afe58b5edf36ddb695288b5.mp3', jaAudio:'7dc5434baf0855eebb92e582e029a20345b97845e829a4e4193eb31762106e1e.mp3'},
  {en:'Turtle', ja:'かめ', vi:'Con rùa', image:'902b679b4e685f770417c9262c9d4f8121f4af6ccfdb50402cb8f5dd78f3519a.jpg', enAudio:'45cb9b72c6f3be6d0575f2569cecb194401011dd1eab63ae5a0ba1f025c31f3b.mp3', jaAudio:'09bbfb051b18ebe24bce16375e8225997e6b849d84d70c71397373ea571754b2.mp3'},
  {en:'Traffic light', ja:'しんごうき', vi:'Đèn giao thông', image:'0246cd330bdae52119143ff501fcb6ab62fd9d8fcbb98edf2ab091bea70fed22.jpg', enAudio:'dfc7be560216ba2bb9a99708483d9fe0de9d5c983c1c76e1a50c1d5b864e75bf.mp3', jaAudio:'2fec581d2293c033e2399957829602cdc453dfd99d1bc819b99adfbe086505a6.mp3'}
];
const screens = [
  ['S01','Main Menu'],['S02','Vocabulary Library'],['S03','Import Excel'],['S04','AI Processing Progress'],
  ['S05','Language Selection'],['S06','Game Configuration'],['S07','Meteor Defense'],['S08','Pause'],
  ['S09','Game Results'],['S10','Flashcard'],['S11','Settings']
];
const defaults = () => ({screen:'S01',lang:'EN',resolution:'1920',layout:'A',animation:true,reduced:false,toolbar:true,
  purpose:'play',pack:'15',difficulty:'Normal',hint:'TEXT_AND_IMAGE',answerMode:'FULL_WORD',targeting:'AUTO_TAB',
  card:0,flipped:false,progress:0,fileName:'',importError:'',score:1240,combo:3,target:0,drafts:['','',''],
  resolved:[false,false,false],hp:4,fall:[.1,.35,0],fallPx:[0,0,0],toast:'',toastWrong:false,settings:{master:78,speech:90,sfx:60,music:25,text:100},settingsFrom:'S01'});
let state = defaults();
const params = new URLSearchParams(location.search);
if(params.get('capture')==='1') document.body.classList.add('capture');
if(screens.some(([id])=>id===params.get('screen'))) state.screen=params.get('screen');
if(['EN','JA'].includes(params.get('lang'))) state.lang=params.get('lang');
if(['A','B'].includes(params.get('layout'))) state.layout=params.get('layout');
if(['1920','1366','1280'].includes(params.get('size'))) state.resolution=params.get('size');
if(params.get('toolbar')==='0') state.toolbar=false;
if(['FULL_WORD','FILL_IN_THE_BLANK'].includes(params.get('answer'))) state.answerMode=params.get('answer');
if(params.get('motion')==='off') state.reduced=true;
const screenEl=document.getElementById('screen');
const frame=document.getElementById('frame');
const live=document.getElementById('liveStatus');
let audio=null,progressTimer=null,toastTimer=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img=(src,alt='',cls='')=>`<img class="${cls}" src="${src}" alt="${esc(alt)}">`;
const btn=(text,action,cls='secondary',extra='')=>`<button type="button" class="game-button ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const badge=(text,cls='')=>`<span class="chip ${cls}">${text}</span>`;
const note=(text,more='')=>`<span class="review-note ${more}">${text}</span>`;
const head=(title,crumb,back='S01')=>`<header class="topbar"><div class="row"><button class="back-button" type="button" data-go="${back}">← Quay lại</button><span class="brand">WORD ORBIT <span class="micro">· TÊN TẠM</span></span></div><div class="breadcrumbs">${crumb} / <strong>${title}</strong></div><div class="top-actions">${note('BẢN XEM THỬ')}</div></header>`;
function setStatus(message){live.textContent=message}
function urlSync(){const p=new URLSearchParams(location.search);p.set('screen',state.screen);p.set('lang',state.lang);p.set('layout',state.layout);p.set('answer',state.answerMode);p.set('size',state.resolution);p.set('toolbar',state.toolbar?'1':'0');p.set('motion',state.reduced?'off':'on');history.replaceState(null,'',`${location.pathname}?${p}`)}
function syncToolbar(){
  document.getElementById('reviewToolbar').hidden=!state.toolbar;
  document.getElementById('showToolbar').hidden=state.toolbar;
  document.getElementById('screenJump').value=state.screen;
  document.getElementById('languageJump').value=state.lang;
  document.getElementById('resolutionJump').value=state.resolution;
  document.getElementById('layoutJump').value=state.layout;
  document.getElementById('animationJump').checked=state.animation;
  document.getElementById('motionJump').checked=state.reduced;
  document.getElementById('answerJump').value=state.answerMode;
  reserveToolbar();
  frame.style.setProperty('--preview-width',`${state.resolution}px`);
  document.body.classList.toggle('reduce-motion',state.reduced);
  document.body.classList.toggle('paused',state.screen==='S08');
  urlSync();
}
function reserveToolbar(){const h=document.getElementById('reviewToolbar').offsetHeight;document.body.style.setProperty('--tb',h?`${h+16}px`:'0px')}
addEventListener('resize',reserveToolbar);
function goto(id){
  if(!screens.some(([key])=>key===id))return;
  if(progressTimer&&id!=='S04'){clearInterval(progressTimer);progressTimer=null}
  if(audio){audio.pause();audio=null}
  state.screen=id;
  if(id==='S04'&&state.progress===0)startProgress();
  render();setStatus(`Màn hình ${id}: ${screens.find(([key])=>key===id)[1]}`);
}
function render(){
  syncToolbar();
  const map={S01:menu,S02:library,S03:importExcel,S04:processing,S05:language,S06:configuration,S07:gameplay,S08:pause,S09:results,S10:flashcard,S11:settings};
  const typing=document.activeElement?.id==='answerInput';
  screenEl.innerHTML=map[state.screen]();
  // Animate only real screen changes, not re-renders caused by typing or toasts.
  if(render.last!==state.screen){screenEl.classList.remove('enter');void screenEl.offsetWidth;screenEl.classList.add('enter');render.last=state.screen;clearTimeout(render.t);render.t=setTimeout(()=>screenEl.classList.remove('enter'),260)}
  if(state.screen==='S07'||state.screen==='S08'){
    const input=document.getElementById('answerInput');
    if(input){input.value=state.drafts[state.target]||'';if(typing&&state.screen==='S07')input.focus()}
  }
}
function menu(){return `<section class="menu-screen"><div class="menu-copy">${note('G-002.9 · Ý TƯỞNG GIAO DIỆN')}<div class="kicker" style="margin-top:2.6em">VOCABULARY DEFENSE / GALAXY EDITION</div><h1 class="menu-title">WORD<br><span>ORBIT</span></h1><p class="menu-lede">Học từ vựng giữa dải ngân hà. Nhập đúng, giữ vững phòng tuyến và ôn lại những từ chưa nhớ.</p><div class="menu-actions">${btn('CHƠI THỬ GIAO DIỆN','play','')}${btn('FLASHCARD','flashcard')}${btn('THƯ VIỆN TỪ','library')}${btn('CÀI ĐẶT','settings')}${btn('THOÁT BẢN XEM THỬ','exit','secondary')}</div></div><div class="menu-art"><div class="orbit"></div><div class="orbit two"></div>${img(assets.planet,'','planet')}${img(assets.ship,'','ship-hero')}</div><div class="menu-bottom"><span>ENGLISH · 日本語 · TIẾNG VIỆT</span><span>DESKTOP 2D / VISUAL PROTOTYPE</span></div></section>`}
function library(){return `${head('Thư viện từ vựng','01 / THƯ VIỆN')}<div class="content two-col"><section><div class="kicker">CHỌN NỘI DUNG</div><h1 class="section-title">Vocabulary Library</h1><p class="body-copy">Pack bên dưới lấy số liệu từ các báo cáo thử nghiệm cục bộ. Chúng chưa có item <code>ready</code>; nút xem trước chỉ dẫn tới mockup giao diện.</p><div class="pack-list"><button type="button" class="pack-item ${state.pack==='15'?'selected':''}" data-pack="15">${img(assets.meteor,'','pack-icon')}<div><strong>Excel 15 từ · Pack v46</strong><span>Metadata thực: 15 mục · EN/JA · test_only · 15 needs_review</span></div>${badge('0 READY','warn')}</button><button type="button" class="pack-item ${state.pack==='100'?'selected':''}" data-pack="100">${img(assets.meteorAlt,'','pack-icon')}<div><strong>Benchmark 100 từ · Pack v301</strong><span>Metadata thực: 100 mục · EN/JA · 99 needs_review · 1 failed</span></div>${badge('0 READY','warn')}</button></div><div class="row wrap" style="margin-top:1.4em">${btn('IMPORT EXCEL','import','secondary')}${btn('XEM TRƯỚC GAME','to-language-play','slim')}${btn('XEM FLASHCARD','to-language-flash','secondary slim')}</div></section><aside class="side"><div class="panel accent"><div class="kicker">PACK ĐANG XEM</div><h2 class="sub-title">${state.pack==='15'?'Excel 15 từ · v46':'Benchmark 100 từ · v301'}</h2><div class="stat-grid"><div class="stat-card"><b>${state.pack==='15'?'15':'100'}</b><span>Tổng mục</span></div><div class="stat-card"><b>0</b><span>Ready</span></div><div class="stat-card"><b>${state.pack==='15'?'15':'99'}</b><span>Chờ review</span></div></div><div class="hairline"></div><div class="row wrap">${badge('EN → VI')}${badge('JA → VI')}${badge('Chỉ dùng nội bộ','warn')}</div><p class="body-copy small">Bản xem thử có thể trình diễn điều hướng với dữ liệu mẫu. Gameplay thật sẽ khóa Start khi không đủ item <code>ready</code>.</p></div><div class="panel subtle"><h3 class="panel-title">Tình trạng nội dung</h3><p class="body-copy">Ảnh và âm thanh trong pack không được xem là đã duyệt chỉ vì tệp tồn tại. Không có AI hoặc Docker chạy trong mockup này.</p></div></aside></div>`}
function importExcel(){return `${head('Import Excel','02 / THƯ VIỆN','S02')}<div class="content two-col"><section><div class="kicker">MÔ PHỎNG GIAO DIỆN</div><h1 class="section-title">Đưa từ mới vào thư viện</h1><p class="body-copy">Chọn tệp để xem trạng thái giao diện. Mockup không đọc workbook, không kiểm tra hàng/cột và không tạo job.</p><label class="file-field"><span class="sub-title">Chọn tệp .xlsx</span><br><input id="mockFile" type="file" accept=".xlsx" aria-label="Chọn tệp Excel để mô phỏng"></label><p id="fileState" class="small ${state.importError?'error':'muted'}">${state.importError?esc(state.importError):state.fileName?`Đã chọn: ${esc(state.fileName)} · chưa được xác thực`:'Chưa chọn tệp · bản xem thử'}</p><div class="row wrap">${btn('XEM TIẾN ĐỘ MÔ PHỎNG','start-processing','')}${btn('QUAY VỀ THƯ VIỆN','library','secondary')}</div></section><aside class="panel"><div class="kicker">XEM TRƯỚC DỮ LIỆU · MINH HỌA</div><h2 class="sub-title">Mẫu bảng từ vựng</h2><table class="table-like"><thead><tr><th>English</th><th>Japanese</th><th>Vietnamese</th></tr></thead><tbody><tr><td>pineapple</td><td>パイナップル</td><td>quả dứa</td></tr><tr><td>traffic light</td><td>しんごうき</td><td>đèn giao thông</td></tr><tr><td>turtle</td><td>かめ</td><td>con rùa</td></tr></tbody></table><div class="hairline"></div><div class="process-line"><span>1</span><b>Kiểm tra cấu trúc</b><small>Chỉ minh họa</small></div><div class="process-line"><span>2</span><b>Xem trước và xác nhận</b><small>Chỉ minh họa</small></div><div class="process-line"><span>3</span><b>Xử lý media</b><small>Không chạy thật</small></div></aside></div>`}
function processing(){const p=state.progress;return `${head('AI Processing Progress','03 / IMPORT','S02')}<div class="content two-col"><section><div class="kicker">TIẾN ĐỘ MÔ PHỎNG</div><h1 class="section-title">Chuẩn bị Content Pack</h1><p class="body-copy">Hoạt ảnh bên dưới chỉ trình diễn cách trình bày trạng thái. Không có request AI, Docker, file xuất hay tác vụ nền.</p><div class="panel accent"><div class="row"><strong>${p<100?'Đang trình diễn...':'Mô phỏng hoàn tất'}</strong><span class="spacer"></span><strong>${p}%</strong></div><div class="bar" style="margin:.8em 0"><span style="width:${p}%"></span></div><span class="small muted">15 mục mẫu · 0 mục được tự động đánh dấu ready</span></div><div class="row wrap" style="margin-top:1em">${btn('XEM LỖI MÔ PHỎNG','processing-error','secondary')}${btn('TRỞ VỀ THƯ VIỆN','library','secondary')}</div></section><aside class="panel"><h2 class="sub-title">Trạng thái từng bước</h2><div class="process-list"><div class="process-line"><span>${p>10?'✓':'·'}</span><b>Đọc từ vựng</b><small>${p>10?'Mô phỏng xong':'Chờ'}</small></div><div class="process-line"><span>${p>40?'✓':'·'}</span><b>Chọn ảnh</b><small>${p>40?'Mô phỏng xong':'Chờ'}</small></div><div class="process-line"><span>${p>75?'✓':'·'}</span><b>Âm thanh EN / JA</b><small>${p>75?'Mô phỏng xong':'Chờ'}</small></div><div class="process-line"><span>${p===100?'!':'·'}</span><b>Review nội dung</b><small>${p===100?'Vẫn cần người duyệt':'Chờ'}</small></div></div><p class="small error" id="processingError"></p></aside></div>`}
function language(){return `${head('Chọn ngôn ngữ','04 / CHỌN CHẾ ĐỘ','S02')}<div class="content two-col"><section><div class="kicker">CHUNG MỘT CONTENT PACK</div><h1 class="section-title">Bạn muốn học từ nào?</h1><div class="choice-grid"><button class="choice ${state.lang==='EN'?'selected':''}" data-lang="EN"><strong>English → Tiếng Việt</strong><small>Pineapple · Traffic light · Frequently</small></button><button class="choice ${state.lang==='JA'?'selected':''}" data-lang="JA"><strong>日本語 → Tiếng Việt</strong><small>りんご · パイナップル · 信号機 · 食べる</small></button></div><p class="body-copy">Ngôn ngữ được chọn thay đổi chữ nguồn và âm đọc trong preview. Nghĩa tiếng Việt giữ nguyên.</p><div class="row">${btn(state.purpose==='flash'?'ĐẾN FLASHCARD':'TIẾP TỤC CẤU HÌNH','language-next','')}</div></section><aside class="panel accent"><div class="kicker">MẪU CHỮ BA NGÔN NGỮ</div><h2 class="sub-title">Đọc nhanh trong không gian tối</h2><div class="sample-line">Pineapple · Traffic light · Frequently</div><div class="sample-line">Quả dứa · Đèn giao thông · Tiếng Việt · Thường xuyên</div><div class="sample-line ja">りんご · パイナップル · 信号機 · 日本語 · 食べる</div><div class="hairline"></div>${badge('0 item ready trong pack hiện tại','warn')}<p class="small muted">Bản xem thử dùng ví dụ và không mở khóa gameplay thật.</p></aside></div>`}
function choice(label,kind,value,description,disabled=false){return `<button type="button" class="choice ${state[kind]===value?'selected':''}" data-kind="${kind}" data-value="${value}" ${disabled?'disabled':''}><strong>${label}</strong><small>${description}</small></button>`}
function configuration(){return `${head('Cấu hình ván chơi','05 / CHUẨN BỊ','S05')}<div class="content two-col"><section><div class="kicker">THÔNG SỐ THỬ NGHIỆM</div><h1 class="section-title">Sẵn sàng phòng thủ?</h1><div class="panel narrow"><div class="form-label">ĐỘ KHÓ · GIÁ TRỊ CHƯA CÂN BẰNG</div><div class="choice-grid">${['Easy','Normal','Hard','Expert'].map(v=>choice(v,'difficulty',v,({Easy:'Chậm · 5 HP',Normal:'Vừa · 4 HP',Hard:'Nhanh · 3 HP',Expert:'Rất nhanh · 2 HP'})[v])).join('')}</div></div><div class="panel narrow" style="margin-top:.8em"><div class="form-label">GỢI Ý</div><div class="choice-grid">${choice('Text + Image','hint','TEXT_AND_IMAGE','Nghĩa Việt, chữ đầu và ảnh')}${choice('Text Only','hint','TEXT_ONLY','Nghĩa Việt và chữ đầu')}${choice('Image Only','hint','IMAGE_ONLY','Ảnh phù hợp, không hiện nghĩa Việt')}${choice('No Hint','hint','NO_HINT','Nghĩa Việt là đề bài')}</div></div></section><aside class="side"><div class="panel narrow"><div class="form-label">KIỂU ĐÁP ÁN</div><div class="choice-grid">${choice('Full Word','answerMode','FULL_WORD','Nhập toàn bộ từ nguồn')}${choice('Fill-in-the-Blank','answerMode','FILL_IN_THE_BLANK','Nhập các ký tự bị ẩn')}</div></div><div class="panel narrow"><div class="form-label">CHỌN MỤC TIÊU</div><div class="choice-grid">${choice('Auto + Tab','targeting','AUTO_TAB','Tự khóa; Tab đổi thủ công')}${choice('Manual Tab','targeting','MANUAL','Phương án so sánh · chưa duyệt',true)}</div></div><div class="panel accent"><div class="kicker">XEM TRƯỚC CÂU HỎI</div><div class="sample-line">Quả dứa <span class="muted">→</span> ${state.answerMode==='FULL_WORD'?(state.lang==='EN'?'Pineapple':'パイナップル'):(state.lang==='EN'?'p _ n e _ p p l e':'パ _ ナ ッ プ ル')}</div><div class="hairline"></div><div class="row wrap">${badge('Chỉ mô phỏng giao diện','warn')}${badge('0 item ready','warn')}</div><p class="small muted">Chế độ ảnh và bộ lọc câu hợp lệ chưa được kiểm thử ở đây.</p>${btn('XEM GAMEPLAY MÔ PHỎNG','start-game','')}</div></aside></div>`}
// Full Word: show this meteor's own draft (per-meteor partial input), else the first-character hint of Text modes.
function fullWordLabel(i,word){const d=state.drafts[i];if(d)return esc(d)+'▏';return ['TEXT_AND_IMAGE','TEXT_ONLY'].includes(state.hint)?esc([...word][0])+' …':'…'}
const meteors=()=>[0,1,2].map((i)=>{
  const words=state.lang==='EN'?[['Quả dứa','Pineapple','p _ n e _ p p l e'],['Đèn giao thông','Traffic light','T r _ f f i c  l _ g h t'],['Thường xuyên','Frequently','F r e _ u e n t l y']]:[['Quả dứa','パイナップル','パ _ ナ ッ プ ル'],['Đèn giao thông','信号機','信 _ 機'],['Thường xuyên','よく','よ _']];
  const w=words[i],x=[20,52,81][i],y=[10,34,6][i],dur=[27,31,29][i];
  const thumb=[cards[0].image,cards[2].image,null][i];
  const showImage=['TEXT_AND_IMAGE','IMAGE_ONLY'].includes(state.hint)&&thumb;
  const clue=(state.hint==='IMAGE_ONLY'?(thumb?'':'KHÔNG CÓ ẢNH · KHÔNG HỢP LỆ'):w[0])+(showImage?img(MEDIA+thumb,'','meteor-thumb'):'');
  const answer=state.answerMode==='FULL_WORD'?fullWordLabel(i,w[1]):w[2];
  return `<button type="button" class="meteor ${state.layout==='B'?'layout-b':''} ${state.target===i?'selected':''} ${state.resolved[i]?'resolved':''} ${state.fall[i]>.75?'danger':''}" data-target="${i}" style="--x:${x}%;--y:${y}%;translate:0 ${state.fallPx[i]}px" aria-label="Thiên thạch ${i+1}, ${esc(w[0])},${state.target===i?'đang được chọn':'chưa chọn'}"><span class="meteor-clue">${clue}</span><span class="meteor-body">${img(i===1?assets.meteorAlt:assets.meteor,'','meteor-sprite')}${img(assets.reticle,'','meteor-reticle')}</span><span class="meteor-label">${answer}</span></button>`
}).join('');
function gameplayCore(){return `<div class="game-scene"><div class="game-hud"><div class="hud-group"><div class="hud-box"><small>HP / PHÒNG TUYẾN</small><div class="hp-lives">${Array.from({length:4},(_,k)=>img(assets.hp,'',k<state.hp?'':'lost')).join('')}</div></div><div class="hud-box"><small>WAVE</small><strong>02 / 03</strong></div></div><div class="hud-group"><div class="hud-box"><small>SCORE · MÔ PHỎNG</small><strong id="scoreValue">${state.score.toLocaleString('en-US')}</strong></div><div class="hud-box"><small>COMBO</small><strong id="comboValue">× ${state.combo}</strong></div><button type="button" class="icon-button" data-action="pause" aria-label="Tạm dừng">Ⅱ</button></div></div><div class="meteor-field">${meteors()}<div class="lane-line"></div></div><div class="defense-line"></div><div class="game-floor"></div>${img(assets.flame,'','ship-flame')}${img(assets.ship,'Tàu phòng thủ','ship')}<div class="answer-console"><label for="answerInput">ĐÁP ÁN</label><input id="answerInput" type="text" autocomplete="off" spellcheck="false" aria-label="Nhập đáp án xem thử" placeholder="${state.lang==='EN'?'Gõ từ tiếng Anh':'Nhập bằng IME tiếng Nhật'}"><button class="game-button slim" type="button" data-action="submit-answer">ENTER</button></div><div class="game-help"><strong>TAB</strong> đổi mục tiêu · <strong>ENTER</strong> xem phản hồi<br>${state.lang==='JA'?'IME browser chỉ để xem thử, không chứng minh Unity':'Ví dụ EN → VI'} · 3 thiên thạch cùng lúc</div>${state.toast?`<div class="game-toast ${state.toastWrong?'wrong':''}">${esc(state.toast)}</div>`:''}<div class="screen-footer">${note('GAMEPLAY MÔ PHỎNG · KHÔNG DÙNG PACK READY','danger-note')}<span>BỐ CỤC ${state.layout} · ${state.answerMode==='FULL_WORD'?'FULL WORD':'FILL-IN-THE-BLANK'}</span></div></div>`}
function gameplay(){return gameplayCore()}
function pause(){return `${gameplayCore()}<div class="pause-overlay"><div class="panel accent pause-card"><div class="kicker">VÁN CHƠI TẠM DỪNG</div><h1 class="section-title">PAUSE</h1><p class="body-copy">Chuyển động và âm thanh được tạm dừng trong bản xem thử.</p><div class="stack">${btn('TIẾP TỤC','resume','')}${btn('CHƠI LẠI','restart','secondary')}${btn('CÀI ĐẶT','pause-settings','secondary')}${btn('VỀ MAIN MENU','pause-exit','danger')}</div></div></div>`}
function results(){return `${head('Kết quả ván chơi','07 / KẾT QUẢ','S01')}<div class="content two-col"><section><div class="kicker">SỐ LIỆU MÔ PHỎNG</div><h1 class="section-title">Phòng tuyến hoàn tất</h1><div class="panel accent result-hero"><div><span class="small muted">TỔNG ĐIỂM</span><div class="result-score">4,280</div><span class="small gold">WAVE 03 / 03 · VICTORY MÔ PHỎNG</span></div>${img(assets.shield,'','pack-icon')}</div><div class="stat-grid" style="margin:1em 0"><div class="stat-card"><b>24</b><span>Đúng</span></div><div class="stat-card"><b>3</b><span>Nhập sai</span></div><div class="stat-card"><b>6</b><span>Bỏ lỡ</span></div></div><div class="row wrap">${badge('Accuracy 80%')}${badge('Combo cao nhất ×5')}${badge('Ngôn ngữ '+state.lang+' → VI')}</div></section><aside class="side"><div class="panel"><div class="kicker">TỪ CẦN ÔN · MINH HỌA</div><h2 class="sub-title">Đừng để từ này trôi qua</h2><div class="review-items">${badge('Traffic light / Đèn giao thông')}${badge('Turtle / Con rùa')}${badge('Frequently / Thường xuyên')}</div><div class="hairline"></div><p class="small muted">Kết quả minh họa, không được tính từ lần nhập trong mockup.</p></div><div class="panel narrow stack">${btn('CHƠI LẠI BẢN XEM THỬ','replay','')}${btn('ÔN BẰNG FLASHCARD','review','secondary')}${btn('THƯ VIỆN TỪ','library','secondary')}${btn('MAIN MENU','menu','secondary')}</div></aside></div>`}
function flashcard(){const c=cards[state.card];const word=state.lang==='EN'?c.en:c.ja;return `${head('Flashcard','08 / HỌC TỪ','S05')}<div class="content"><div class="row" style="justify-content:space-between;margin-bottom:1em"><div><div class="kicker">FLASHCARD / ${state.lang} → VI</div><h1 class="section-title" style="font-size:2.4cqw;margin:0">Học lại theo nhịp của bạn</h1></div>${badge('MEDIA THẬT · NEEDS_REVIEW','warn')}</div><div class="panel no-pad flash-frame"><div class="flash-image">${img(MEDIA+c.image,`Ảnh Content Pack của ${c.en}`)}<span class="media-tag">Ảnh pack thử nghiệm · chưa duyệt phát hành</span></div><div class="flash-content"><div class="kicker">${state.flipped?'MẶT SAU / NGHĨA TIẾNG VIỆT':'MẶT TRƯỚC / TỪ NGUỒN'}</div>${state.flipped?`<div class="flash-meaning flip-back">${c.vi}<br><span class="small muted">${word}</span></div>`:`<div class="flash-word">${word}</div><p class="flash-hint">Nhớ nghĩa tiếng Việt, rồi nhấn <kbd>Space</kbd> hoặc LẬT THẺ</p>`}<p class="flash-meta">${state.card+1} / ${cards.length} · <kbd>←</kbd> <kbd>→</kbd> đổi thẻ · Content Pack v46 · status: needs_review</p><div class="row wrap">${btn('PHÁT ÂM','play-audio','slim')}${btn('LẬT THẺ','flip','secondary slim')}</div><div class="hairline wide"></div><div class="row wrap">${btn('CẦN ÔN','mark-review','secondary slim')}${btn('ĐÃ BIẾT','mark-known','secondary slim')}</div></div></div><div class="flash-controls"><div class="row">${btn('← TRƯỚC','card-prev','secondary slim')}${btn('TIẾP →','card-next','slim')}</div><div class="row" style="min-width:30%"><span class="small">TIẾN ĐỘ MÔ PHỎNG</span><div class="bar grow"><span style="width:${((state.card+1)/cards.length)*100}%"></span></div></div></div></div>`}
function settings(){return `${head('Cài đặt','09 / TÙY CHỈNH',state.settingsFrom)}<div class="content two-col"><section><div class="kicker">CHỈ LƯU TRONG PHIÊN XEM THỬ</div><h1 class="section-title">Settings</h1><div class="panel"><h2 class="sub-title">Âm thanh</h2>${[['master','Âm lượng chung'],['speech','Phát âm từ vựng'],['sfx','Hiệu ứng'],['music','Nhạc nền · tùy chọn']].map(([key,label])=>`<label class="settings-row"><span>${label}</span><input class="slider" type="range" min="0" max="100" value="${state.settings[key]}" data-setting="${key}"><strong id="value-${key}">${state.settings[key]}%</strong></label>`).join('')}<div class="hairline"></div><label class="settings-row"><span>Cỡ chữ</span><input class="slider" type="range" min="85" max="120" value="${state.settings.text}" data-setting="text"><strong id="value-text">${state.settings.text}%</strong></label><label class="row"><input id="reduceSetting" type="checkbox" ${state.reduced?'checked':''}> Giảm chuyển động trang trí</label></div><div class="row wrap" style="margin-top:1em">${btn('LƯU CHO BẢN XEM THỬ','save-settings','')}${btn('QUAY LẠI','settings-back','secondary')}</div></section><aside class="panel accent"><div class="kicker">KIỂM TRA TYPOGRAPHY</div><h2 class="sub-title">Một màn hình, ba hệ chữ</h2><div class="sample-line">Pineapple · Traffic light · Frequently</div><div class="sample-line">Quả dứa · Đèn giao thông · Tiếng Việt · Thường xuyên</div><div class="sample-line ja">りんご · パイナップル · 信号機 · 日本語 · 食べる</div><div class="hairline"></div><p class="body-copy">Font hiện tại là Noto Sans JP với Noto Sans. Render trong trình duyệt không chứng minh TextMeshPro hoặc IME của Unity sẽ hoạt động giống vậy.</p></aside></div>`}
function startProgress(){state.progress=0;clearInterval(progressTimer);progressTimer=setInterval(()=>{if(state.screen!=='S04'){clearInterval(progressTimer);progressTimer=null;return}state.progress=Math.min(100,state.progress+5);render();if(state.progress===100){clearInterval(progressTimer);progressTimer=null}},220)}
function toast(message,wrong=false){state.toast=message;state.toastWrong=wrong;render();clearTimeout(toastTimer);toastTimer=setTimeout(()=>{state.toast='';if(state.screen==='S07')render()},1200)}
function effect(){if(!['S07','S08'].includes(state.screen))goto('S07');const layer=document.getElementById('effectLayer');
  // Aim from the ship to the selected meteor's sprite, in frame-relative coordinates.
  const f=frame.getBoundingClientRect(),m=document.querySelector(`[data-target="${state.target}"] .meteor-body`)?.getBoundingClientRect();
  const tx=m?(m.left+m.width/2-f.left)/f.width*100:51,ty=m?(m.top+m.height/2-f.top)/f.height*100:39;
  const dx=(tx-50)*f.width/100,dy=(85-ty)*f.height/100,len=Math.hypot(dx,dy)/f.height*100,angle=Math.atan2(dx,dy)*180/Math.PI;
  layer.innerHTML=`<div class="beam" style="--angle:${angle}deg;height:${len}%"></div><div class="burst" style="--x:calc(${tx}% - 2em);--y:calc(${ty}% - 2em)"></div><div class="score-pop" style="--x:${tx}%;--y:${ty-6}%">+100</div>`;setTimeout(()=>layer.innerHTML='',850)}
function submit(){if(state.screen!=='S07')return;const input=document.getElementById('answerInput');if(!input)return;state.drafts[state.target]=input.value;const expected=state.lang==='EN'?['pineapple','traffic light','frequently'][state.target]:['パイナップル','信号機','よく'][state.target];const partial=state.lang==='EN'?['ia','ai','q'][state.target]:['イ','号','く'][state.target];const ok=input.value.trim().normalize('NFC').toLocaleLowerCase()===((state.answerMode==='FULL_WORD'?expected:partial).normalize('NFC').toLocaleLowerCase());if(ok){state.score+=100;state.combo++;state.resolved[state.target]=true;state.fall[state.target]=0;state.fallPx[state.target]=0;effect();toast('CHÍNH XÁC · +100');setTimeout(()=>{if(state.screen!=='S07')return;const next=[1,2,0].map(k=>(state.target+k)%3).find(k=>!state.resolved[k]);if(next===undefined){state.resolved=[false,false,false];state.target=0}else state.target=next;state.drafts[state.target]='';render();document.getElementById('answerInput')?.focus()},950)}else{state.combo=0;toast(`Chưa đúng với “${['Quả dứa','Đèn giao thông','Thường xuyên'][state.target]}” · combo về 0 · sửa rồi nhấn Enter`,true);document.querySelector(`[data-target="${state.target}"]`)?.classList.add('wrong')}}
document.addEventListener('click',e=>{
  const go=e.target.closest('[data-go]');if(go){goto(go.dataset.go);return}
  const target=e.target.closest('[data-target]');if(target){state.target=Number(target.dataset.target);render();document.getElementById('answerInput')?.focus();return}
  const pack=e.target.closest('[data-pack]');if(pack){state.pack=pack.dataset.pack;render();return}
  const lang=e.target.closest('[data-lang]');if(lang){state.lang=lang.dataset.lang;render();return}
  const choiceEl=e.target.closest('[data-kind]');if(choiceEl){state[choiceEl.dataset.kind]=choiceEl.dataset.value;render();return}
  const a=e.target.closest('[data-action]')?.dataset.action;if(!a)return;
  const actions={play:()=>{state.purpose='play';goto('S02')},flashcard:()=>{state.purpose='flash';goto('S02')},library:()=>goto('S02'),import:()=>goto('S03'),settings:()=>{state.settingsFrom='S01';goto('S11')},exit:()=>{setStatus('Đây là bản xem thử trong trình duyệt. Có thể đóng tab để thoát.');alert('Đây là bản xem thử. Đóng tab trình duyệt để thoát.')},'to-language-play':()=>{state.purpose='play';goto('S05')},'to-language-flash':()=>{state.purpose='flash';goto('S05')},'language-next':()=>goto(state.purpose==='flash'?'S10':'S06'),'start-processing':()=>{state.progress=0;goto('S04')},'processing-error':()=>{const el=document.getElementById('processingError');if(el)el.textContent='Mô phỏng lỗi: Docker không khả dụng. Không có tác vụ thật nào được gửi.'},'start-game':()=>{state.hp=4;state.fall=[.1,.35,0];state.fallPx=[0,0,0];state.resolved=[false,false,false];state.drafts=['','',''];state.target=0;goto('S07')},pause:()=>goto('S08'),resume:()=>goto('S07'),restart:()=>{state.hp=4;state.fall=[.1,.35,0];state.fallPx=[0,0,0];state.resolved=[false,false,false];state.drafts=['','',''];state.target=0;goto('S07')},'pause-settings':()=>{state.settingsFrom='S08';goto('S11')},'pause-exit':()=>{if(confirm('Rời bản xem thử và về Main Menu?'))goto('S01')},'submit-answer':submit,replay:()=>goto('S06'),review:()=>{state.purpose='flash';goto('S10')},menu:()=>goto('S01'),flip:()=>{state.flipped=!state.flipped;render()},'card-prev':()=>{state.card=(state.card+cards.length-1)%cards.length;state.flipped=false;goto('S10')},'card-next':()=>{state.card=(state.card+1)%cards.length;state.flipped=false;goto('S10')},'play-audio':()=>{const c=cards[state.card];if(audio)audio.pause();audio=new Audio(MEDIA+(state.lang==='EN'?c.enAudio:c.jaAudio));audio.volume=state.settings.speech/100*state.settings.master/100;audio.play().then(()=>setStatus('Đang phát âm thanh mẫu từ pack needs_review')).catch(()=>setStatus('Trình duyệt không phát được âm thanh mẫu'))},'mark-review':()=>{setStatus('Đã đánh dấu cần ôn trong phiên xem thử')},'mark-known':()=>{setStatus('Đã đánh dấu đã biết trong phiên xem thử')},'save-settings':()=>{setStatus('Đã áp dụng cài đặt tạm trong bản xem thử');goto(state.settingsFrom)},'settings-back':()=>goto(state.settingsFrom)};
  actions[a]?.();
});
document.addEventListener('change',e=>{if(e.target.id==='mockFile'){const f=e.target.files[0];state.fileName=f?.name||'';state.importError=f&&!f.name.toLowerCase().endsWith('.xlsx')?'Chỉ minh họa: định dạng này không phải .xlsx':'';render()}if(e.target.id==='reduceSetting'){state.reduced=e.target.checked;syncToolbar()}});
document.addEventListener('input',e=>{if(e.target.id==='answerInput'){state.drafts[state.target]=e.target.value;const label=document.querySelector(`[data-target="${state.target}"] .meteor-label`);if(label&&state.answerMode==='FULL_WORD')label.innerHTML=fullWordLabel(state.target,'')}if(e.target.dataset.setting){state.settings[e.target.dataset.setting]=Number(e.target.value);const v=document.getElementById(`value-${e.target.dataset.setting}`);if(v)v.textContent=`${e.target.value}%`}});
document.addEventListener('keydown',e=>{if(state.screen==='S10'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)){const k={' ':'flip',ArrowLeft:'card-prev',ArrowRight:'card-next'}[e.key];if(k){e.preventDefault();document.querySelector(`[data-action="${k}"]`)?.click()}return}if(state.screen!=='S07')return;if(e.isComposing||e.keyCode===229)return;if(e.key==='Tab'&&document.activeElement?.id==='answerInput'){e.preventDefault();state.target=[1,2].map(k=>(state.target+k)%3).find(k=>!state.resolved[k])??state.target;render();document.getElementById('answerInput')?.focus()}if(e.key==='Enter'&&document.activeElement?.id==='answerInput'){e.preventDefault();submit()}if(e.key==='Escape'){e.preventDefault();goto('S08')}});
const toolbar=document.getElementById('reviewToolbar');
document.getElementById('screenJump').innerHTML=screens.map(([id,name])=>`<option value="${id}">${id} · ${name}</option>`).join('');
toolbar.addEventListener('change',e=>{const id=e.target.id;if(id==='screenJump')goto(e.target.value);if(id==='languageJump'){state.lang=e.target.value;render()}if(id==='resolutionJump'){state.resolution=e.target.value;syncToolbar()}if(id==='layoutJump'){state.layout=e.target.value;render()}if(id==='answerJump'){state.answerMode=e.target.value;render()}if(id==='animationJump'){state.animation=e.target.checked;syncToolbar()}if(id==='motionJump'){state.reduced=e.target.checked;syncToolbar()}});
document.getElementById('hideToolbar').onclick=()=>{state.toolbar=false;syncToolbar()};
document.getElementById('showToolbar').onclick=()=>{state.toolbar=true;syncToolbar()};
document.getElementById('effectTrigger').onclick=effect;
document.getElementById('resetPreview').onclick=()=>{state=defaults();render();setStatus('Đã đặt lại bản xem thử')};

// Falling starfield from the protected historical concept: depth, spring/damping, twinkle.
const canvas=document.getElementById('starfield'),ctx=canvas.getContext('2d');
let stars=[],pointerX=0,lastTime=performance.now(),width=0,height=0;
function resizeStars(){const r=frame.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);width=r.width;height=r.height;canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);stars=Array.from({length:135},(_,i)=>({baseX:Math.random()*width,x:Math.random()*width,y:Math.random()*height,depth:.2+Math.random()*.8,size:.55+Math.random()*1.25,vx:0,speed:2+Math.random()*10,alpha:.2+Math.random()*.42,phase:Math.random()*6.28,twinkle:.4+Math.random()*.9,sparkle:i%56===0}))}
new ResizeObserver(resizeStars).observe(frame);
frame.addEventListener('pointermove',e=>{const r=frame.getBoundingClientRect();pointerX=(e.clientX-r.left)/r.width*2-1});
frame.addEventListener('pointerleave',()=>pointerX=0);
// shortcut: mock descent only (fixed speeds, no spawn queue); real timing comes from the Gameplay spec in G-003.
const FALL_SECONDS=[22,26,24];
function impact(i){state.fall[i]=0;state.fallPx[i]=0;state.drafts[i]='';state.combo=0;state.hp=Math.max(0,state.hp-1);
  // toast() re-renders the scene, so flash the new scene element afterwards.
  if(state.hp===0){state.hp=4;toast('Phòng tuyến thủng · bản xem thử hồi lại HP',true)}else toast(`Thiên thạch “${['Quả dứa','Đèn giao thông','Thường xuyên'][i]}” chạm phòng tuyến · −1 HP`,true);
  document.querySelector('.game-scene')?.classList.add('hit')}
function stepMeteors(dt){if(!['S07','S08'].includes(state.screen))return;const field=document.querySelector('.meteor-field');if(!field)return;
  document.querySelectorAll('.meteor[data-target]').forEach(el=>{const i=Number(el.dataset.target);if(state.resolved[i])return;
    if(state.screen==='S07'){state.fall[i]+=dt/FALL_SECONDS[i];if(state.fall[i]>=1){impact(i);return}}
    const max=Math.max(0,field.clientHeight-el.offsetTop-el.offsetHeight);state.fallPx[i]=Math.round(state.fall[i]*max);
    el.style.translate=`0 ${state.fallPx[i]}px`;el.classList.toggle('danger',state.fall[i]>.75)})}
function drawStars(now){const dt=Math.min((now-lastTime)/1000,.05);lastTime=now;stepMeteors(dt);ctx.clearRect(0,0,width,height);const moving=state.animation&&!state.reduced&&!matchMedia('(prefers-reduced-motion: reduce)').matches;for(const s of stars){if(moving){s.y+=s.speed*s.depth*dt;if(s.y>height+5)s.y=-5;const target=s.baseX+pointerX*22*s.depth;s.vx=(s.vx+(target-s.x)*.009)*.87;s.x+=s.vx}const a=s.alpha+(moving?Math.sin(now/1000*s.twinkle+s.phase)*.12:0);ctx.globalAlpha=Math.max(.1,Math.min(.8,a))*(state.screen==='S07'||state.screen==='S08'?.7:1);ctx.fillStyle=s.sparkle?'#f8e7af':'#b8f9ff';if(s.sparkle){ctx.fillRect(s.x-2,s.y,4,1);ctx.fillRect(s.x,s.y-2,1,4)}else{ctx.beginPath();ctx.arc(s.x,s.y,s.size*s.depth,0,Math.PI*2);ctx.fill()}}ctx.globalAlpha=1;requestAnimationFrame(drawStars)}
requestAnimationFrame(drawStars);
render();
